// strings.js — the game's UI texts in English and German (#9). Pure: no DOM, no window, so node --test can import it.
// A value is either a string or a function of the call's arguments. Proper names (checkpoints, landmarks, streets,
// Gemeinden) are passed in as arguments and never translated.
// Strings may carry <b>/<br>/<span> markup: they are our own constants and are written with innerHTML.

const small = (s) => `<span style="font-size:17px">${s}</span>`;

